from pathlib import Path
import hashlib,json,struct
ROOT=Path('.')
binary=(ROOT/'analysis/derived/TT.unpacked.exe').read_bytes()
expected=next(a['sha256'] for a in json.loads((ROOT/'analysis/toolchain.json').read_text())['artifacts'] if a['path'].endswith('TT.unpacked.exe'))
assert hashlib.sha256(binary).hexdigest()==expected
ds=binary[0xfae0:]
def cstr(o):return ds[o:ds.index(0,o)].decode('cp437')
def choices(o,n):return [cstr(p) for p in struct.unpack_from('<'+'H'*n,ds,o)]
offsets={'levelTitle':0x172d,'scoresTitle':0x123f,'title':0x8008,'gameMenu':0x801c,'roundTitle':0x8026,'roundFooter':0x802c,'roundNumber':0x802d,'score':0x8030,'modePrompt':0x803d,'choiceInstruction':0x8516,'endPrompt':0x102e,'nameDots':0x859c,'nameEnter':0x859f,'playersTitle':0x8054,'playersPrompt':0x805c,'secondNamePrompt':0x8079,'ready':0x8426,'player':0x81cf,'playerScore':0x81dd,'summaryPlayer':0x8448,'hits':0x8456,'misses':0x845f,'accuracy':0x846a,'bonus':0x8479,'gameOverPlayer':0x84a7,'gameOver':0x84b3,'playerOneFinal':0x84c9,'playerTwoFinal':0x84db,'scoreTitle':0x7b20,'scoreHeading':0x7b30,'keysHeading':0x7b6a,'scoreRow':0x7b75,'keysRow':0x7b8b,'ignoredKeys':0x8498,'replacementExcluded':0x84a2}
data={k:cstr(v) for k,v in offsets.items()}
data.update(modeChoices=choices(0x7fc4,2),playerChoices=choices(0x7fe4,2),endChoices=choices(0x7ff0,3),
 introParagraphs=[cstr(o) for o in [0x809a,0x813b]],roundParagraphs=[cstr(o) for o in [0x81ef,0x82ac,0x8356,0x840e]],
 gameOrder=ds[0x7a94:0x7a94+90].decode('ascii'),scoreTables={'count':2,'entries':5,'entryBytes':35,'nameBytes':26,'scoreOffset':26,'keysOffset':30,'dateOffset':31})
data['boomletSound']={'pitches':list(struct.unpack_from('<12I',ds,0x7dd0)),'durationMs':83,'pitHundredths':0x71ca5f0}
# Expand the native17e47 case1 call graph and 8-byte pitch/duration/rest records.
def tones(offset,count=1):return [struct.unpack_from('<IHH',ds,offset+8*i) for i in range(count)]
def phrase_a():return tones(0x7cd0)*2+tones(0x7cd8)
def phrase_b():return tones(0x7cd0)*2+tones(0x7ce0)
def phrase_c():return phrase_a()*2+phrase_b()+tones(0x7ce8,2)
def phrase_d():return tones(0x7d40)*2+tones(0x7d48)
def phrase_e():return tones(0x7d40)*2+tones(0x7d50)
def phrase_f():return phrase_d()*2+phrase_e()+tones(0x7d58,2)
ship=(phrase_c()+phrase_a()+phrase_b()+tones(0x7cf8)*2+tones(0x7d00,2)+tones(0x7cd8)
      +phrase_c()+tones(0x7d10)+tones(0x7cf8)+tones(0x7d18,3)+tones(0x7cf8)
      +tones(0x7d30)+tones(0x7ce0)+tones(0x7d38)+tones(0x7ce0)
      +phrase_f()+phrase_d()+phrase_e()+tones(0x7d68)*2+tones(0x7d70,2)+phrase_f()+tones(0x7d80,10))
assert len(ship)==85
data['wordShipSound']={'notes':ship}
assert data['modeChoices']==['Practice Keys','Full Keyboard']
assert len(data['gameOrder'])==90
out=ROOT/'dist/invaders-data.js'
out.write_text('// Generated by scripts/extract-invaders-data.py; retained static REA evidence.\nexport default '+json.dumps(data,ensure_ascii=False,separators=(',',':'))+';\n')
functions=['0x12f68','0x12f7f','0x19538','0x1980e','0x1947e','0x19296','0x1922d','0x19bec','0x1787b','0x1768e','0x1ab36','0x1a541','0x17e47','0x17a75','0x17ce8','0x17d49','0x1a22a','0x180e1','0x18104','0x1811c','0x18134','0x18152','0x18175','0x1818d','0x181a5']
receipt={'scope':'Static Letter Invaders UI and special-target sound resources; no native runtime capture or named-history score import','binary_sha256':expected,'strings':{k:hex(v) for k,v in offsets.items()},'functions':[{'address':a,'evidence':(ROOT/('analysis/recovered/'+a+'.asm')).read_text().splitlines()[0].lstrip('; ')} for a in functions],'boomlet_sound':{'pitch_table':'DS7dd0[12] uint32','pitch_unit':'hundredths of Hz','octave_divisors':[1,2,4,8,16,32],'note_ms':83,'timer_rounding':'floor((ms*182+5000)/10000) BIOS ticks; zero-length silence entries consume no tick'},'word_ship_sound':{'effect':'0x17e47 case1','tables':'DS7cd0..7dcf; 8-byte uint32 pitch,uint16 duration,uint16 silence','expanded_notes':85,'phrases':['0x180e1','0x18104','0x1811c','0x18134','0x18152','0x18175','0x1818d','0x181a5']},'score_table':{'address':'DS9843','modeCount':2,'entriesPerMode':5,'entryBytes':35,'record_fields':{'name':0,'score':26,'keys':30,'date':31},'note':'Global tail data beyond active profile; no names or score values imported.'},'output_sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'extractor_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}
path=ROOT/'analysis/invaders/resources.json';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(receipt,indent=2)+'\n')
print('Extracted Letter Invaders resources and static identities.')
